import { computed, ref, watch } from 'vue'
import type { TopicListResponse } from '@/api/types'

export function useTopicList(size = 12) {
  const category = ref('')
  const keyword = ref('')
  const page = ref(0)
  const items = ref<TopicListResponse['items']>([])
  const total = ref(0)
  const loading = ref(false)
  const error = ref('')

  let controller: AbortController | null = null

  async function load() {
    controller?.abort()
    controller = new AbortController()
    loading.value = true
    error.value = ''

    const qs = new URLSearchParams({ page: String(page.value), size: String(size) })
    if (category.value) qs.set('category', category.value)
    if (keyword.value) qs.set('q', keyword.value)

    try {
      const res = await fetch(`/api/v1/topics?${qs}`, { signal: controller.signal })
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const data = (await res.json()) as TopicListResponse
      items.value = data.items
      total.value = data.total
    } catch (e) {
      if ((e as Error).name !== 'AbortError') error.value = (e as Error).message
    } finally {
      loading.value = false
    }
  }

  watch([category, keyword], () => { page.value = 0; load() }, { immediate: true })
  watch(page, load)

  return {
    category, keyword, page, items, total, loading, error,
    hasPrev: computed(() => page.value > 0),
    hasNext: computed(() => (page.value + 1) * size < total.value),
  }
}

import { createRouter, createWebHistory } from 'vue-router'
import { useAuthStore } from '@/stores/auth'

const router = createRouter({
  history: createWebHistory(),
  routes: [
    { path: '/', name: 'home', component: () => import('@/views/HomeView.vue') },
    { path: '/catalog', name: 'catalog', component: () => import('@/views/CatalogView.vue') },
    { path: '/topics/:slug', name: 'topic', component: () => import('@/views/TopicDetailView.vue') },
    {
      path: '/me',
      name: 'my-learning',
      component: () => import('@/views/MyLearningView.vue'),
      meta: { requiresAuth: true },
    },
    { path: '/login', name: 'login', component: () => import('@/views/LoginView.vue') },
    {
      path: '/:pathMatch(.*)*',
      name: 'not-found',
      component: () => import('@/views/NotFoundView.vue'),
    },
  ],
  scrollBehavior: () => ({ top: 0 }),
})

router.beforeEach((to) => {
  const auth = useAuthStore()
  if (to.meta.requiresAuth && !auth.isLoggedIn) {
    return { name: 'login', query: { redirect: to.fullPath } }
  }
  if (to.name === 'login' && auth.isLoggedIn) {
    return { name: 'my-learning' }
  }
})

export default router

apiVersion: v1
kind: ConfigMap
metadata:
  name: learnhub-web-nginx
data:
  nginx.conf: |
    server {
      listen 80;
      root /usr/share/nginx/html;
      index index.html;

      # Vue Router history 模式：找不到文件就交给前端路由
      location / {
        try_files $uri $uri/ /index.html;
      }

      # 同源反代，避免生产环境 CORS
      location /api/ {
        proxy_pass http://learnhub-api:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Request-Id $request_id;
      }

      # 带 hash 的静态资源可以放心长缓存
      location ~* \.(js|css|woff2|png|svg)$ {
        expires 1y;
        add_header Cache-Control "public, immutable";
      }

      gzip on;
      gzip_types text/css application/javascript application/json;
    }
